#include <stdio.h>
#include <string.h>

struct Cat {
    char name[20];
    int fish;
};

int main(void) {
    struct Cat a = {"小橘", 2};
    struct Cat b;

    b = a;
    b.fish = b.fish + 1;
    strcpy(b.name, "假小橘");

    printf("a：%s 吃了 %d 条喵\n", a.name, a.fish);
    printf("b：%s 吃了 %d 条喵\n", b.name, b.fish);
    return 0;
}

